describe('listing sessions', () => {
  it('answers list_sessions with ISO session summaries for the session user, an empty list without listFor, and SERVER_ERROR when listFor throws', async () => {
    const sent: OutgoingMessage[] = [];
    const orchestrator = {} as ChatOrchestrator;
    const before = {updatedAt: '2026-01-01T00:05:00.000Z', sessionId: 's3'};
    const seen: Array<{userId: string | number; options: unknown}> = [];
    const withList = createMessageHandler(orchestrator, {
      listFor: (userId, options) => {
        seen.push({userId, options});
        return [
          {
            sessionId: 's2',
            createdAt: new Date('2026-01-01T00:00:00.000Z'),
            updatedAt: new Date('2026-01-01T00:02:00.000Z'),
            entryCount: 3,
          },
        ];
      },
    });
    const withoutList = createMessageHandler(orchestrator);
    const failingList = createMessageHandler(orchestrator, {
      listFor: () => Promise.reject(new Error('store offline')),
    });
    const ws = {send: (raw: string) => sent.push(JSON.parse(raw) as OutgoingMessage)} as unknown as WebSocket;
    const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};

    await withList(ws, session, {type: 'list_sessions', limit: 5, before, userId: 'u2'});

